create extension if not exists pgcrypto;
create table if not exists public.admin_bootstrap(id boolean primary key default true check(id=true),first_admin_id uuid unique references auth.users(id) on delete set null,claimed_at timestamptz);
insert into public.admin_bootstrap(id) values(true) on conflict(id) do nothing;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'customer' check(role in('customer','admin')),is_blocked boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique,name text not null,description text not null default '',category text not null default 'other',material text not null default 'gold' check(material in('gold','silver')),price numeric(14,2) not null default 0 check(price>=0),weight numeric(10,3),image_url text,is_published boolean not null default false,stock integer not null default 0 check(stock>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete restrict,status text not null default 'pending' check(status in('pending','confirmed','processing','shipped','completed','cancelled')),total numeric(14,2) not null default 0 check(total>=0),customer_name text not null,phone text not null,address text not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,unit_price numeric(14,2) not null check(unit_price>=0),quantity integer not null check(quantity>0),created_at timestamptz not null default now());
create table if not exists public.site_settings(key text primary key,value jsonb not null default '{}'::jsonb,is_public boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id) on delete set null,action text not null,entity text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists products_published_idx on public.products(is_published,material);
create index if not exists orders_user_idx on public.orders(user_id,created_at desc);
create index if not exists audit_logs_created_idx on public.audit_logs(created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin' and is_blocked=false); $$;
create or replace function public.can_access_order(target_order uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.orders o where o.id=target_order and (o.user_id=(select auth.uid()) or public.is_admin())); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
declare assigned_role text := 'customer';
begin
 perform 1 from public.admin_bootstrap where id=true for update;
 if not exists(select 1 from public.admin_bootstrap where id=true and first_admin_id is not null) then
  update public.admin_bootstrap set first_admin_id=new.id,claimed_at=now() where id=true and first_admin_id is null;
  if found then assigned_role:='admin'; end if;
 end if;
 insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),assigned_role) on conflict(id) do nothing;
 insert into public.audit_logs(actor_id,action,entity,entity_id,details) values(new.id,'account_created','profile',new.id::text,jsonb_build_object('assigned_role',assigned_role));
 return new;
end; $$;
drop trigger if exists on_auth_user_created_gilver on auth.users;
create trigger on_auth_user_created_gilver after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['profiles','products','orders'] loop execute format('drop trigger if exists %I_updated_at on public.%I',t,t); execute format('create trigger %I_updated_at before update on public.%I for each row execute procedure public.set_updated_at()',t,t); end loop; end $$;
create or replace function public.write_audit_log() returns trigger language plpgsql security definer set search_path='' as $$
declare target_id text; details_json jsonb;
begin
 if tg_op='DELETE' then target_id:=to_jsonb(old)->>'id'; details_json:=jsonb_build_object('before',to_jsonb(old));
 elsif tg_op='INSERT' then target_id:=to_jsonb(new)->>'id'; details_json:=jsonb_build_object('after',to_jsonb(new));
 else target_id:=to_jsonb(new)->>'id'; details_json:=jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(new)); end if;
 insert into public.audit_logs(actor_id,action,entity,entity_id,details) values(auth.uid(),lower(tg_op),tg_table_name,target_id,details_json);
 if tg_op='DELETE' then return old; end if; return new;
end; $$;
drop trigger if exists products_audit on public.products;
create trigger products_audit after insert or update or delete on public.products for each row execute procedure public.write_audit_log();
drop trigger if exists orders_audit on public.orders;
create trigger orders_audit after insert or update on public.orders for each row execute procedure public.write_audit_log();
drop trigger if exists profiles_audit on public.profiles;
create trigger profiles_audit after update on public.profiles for each row execute procedure public.write_audit_log();
drop trigger if exists settings_audit on public.site_settings;
create trigger settings_audit after insert or update or delete on public.site_settings for each row execute procedure public.write_audit_log();
alter table public.admin_bootstrap enable row level security;
alter table public.profiles enable row level security;
alter table public.products enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.site_settings enable row level security;
alter table public.audit_logs enable row level security;
drop policy if exists profiles_select_self_or_admin on public.profiles;
create policy profiles_select_self_or_admin on public.profiles for select to authenticated using(id=(select auth.uid()) or public.is_admin());
drop policy if exists profiles_admin_update on public.profiles;
create policy profiles_admin_update on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists products_public_read on public.products;
create policy products_public_read on public.products for select to anon,authenticated using(is_published=true or public.is_admin());
drop policy if exists products_admin_insert on public.products;
create policy products_admin_insert on public.products for insert to authenticated with check(public.is_admin());
drop policy if exists products_admin_update on public.products;
create policy products_admin_update on public.products for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists products_admin_delete on public.products;
create policy products_admin_delete on public.products for delete to authenticated using(public.is_admin());
drop policy if exists orders_read_owner_admin on public.orders;
create policy orders_read_owner_admin on public.orders for select to authenticated using(user_id=(select auth.uid()) or public.is_admin());
drop policy if exists orders_create_owner on public.orders;
create policy orders_create_owner on public.orders for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');
drop policy if exists orders_admin_update on public.orders;
create policy orders_admin_update on public.orders for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists order_items_read_authorized on public.order_items;
create policy order_items_read_authorized on public.order_items for select to authenticated using(public.can_access_order(order_id));
drop policy if exists order_items_create_owner on public.order_items;
create policy order_items_create_owner on public.order_items for insert to authenticated with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid()) and o.status='pending'));
drop policy if exists settings_public_read on public.site_settings;
create policy settings_public_read on public.site_settings for select to anon,authenticated using(is_public=true or public.is_admin());
drop policy if exists settings_admin_insert on public.site_settings;
create policy settings_admin_insert on public.site_settings for insert to authenticated with check(public.is_admin());
drop policy if exists settings_admin_update on public.site_settings;
create policy settings_admin_update on public.site_settings for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists settings_admin_delete on public.site_settings;
create policy settings_admin_delete on public.site_settings for delete to authenticated using(public.is_admin());
drop policy if exists audit_admin_read on public.audit_logs;
create policy audit_admin_read on public.audit_logs for select to authenticated using(public.is_admin());
grant usage on schema public to anon,authenticated;
grant select on public.products to anon,authenticated;
grant insert,update,delete on public.products to authenticated;
grant select,insert,update on public.orders to authenticated;
grant select,insert on public.order_items to authenticated;
grant select,insert,update,delete on public.site_settings to authenticated;
grant select,update on public.profiles to authenticated;
grant select on public.audit_logs to authenticated;
